def build_rebirth_catalog(base_catalog: dict) -> dict:
    result = {}
    for industry, names in REBIRTH_FACTORY_NAMES.items():
        terminal = max(
            (s for s in base_catalog.values() if s['specialization'] == industry),
            key=lambda s: (s['industry_order'], s['company_level_required'], s['id']),
        )
        previous = terminal['id']
        for rank, name in enumerate(names, 1):
            business_id = f'rebirth_{industry}_{rank}'
            scale = 1 + rank * 0.20
            spec = career_business(
                business_id=business_id, name=name, icon=terminal['icon'],
                specialization=industry, order=int(terminal['industry_order']) + rank,
                open_cost=round(float(terminal['open_cost']) * (1 + rank * 0.35), 2),
                level_required=60,
                inputs={k: v * scale for k, v in terminal['inputs_per_hour'].items()},
                outputs={k: v * scale for k, v in terminal['outputs_per_hour'].items()},
                milestones=('Опытная линия', 'Поточное производство', 'Контроль качества', 'Автономное управление', 'Полная промышленная мощность'),
                milestone_resources=('energy', 'water'),
                description=f'Предприятие {rank}-й ступени перерождения. Развивает выпуск существующих отраслевых товаров и снабжает другие компании.',
                prerequisites={previous: 10}, territory_required=10,
                tags=('rebirth', 'production'), unique=True,
            )
            spec['rebirth_required'] = rank
            result[business_id] = spec
            previous = business_id
    return result
